// Load / save badges for a profile
const badgeKey = (uid) => `stfy_badges_${uid}`;
const loadBadges = (uid) => { try { const r=localStorage.getItem(badgeKey(uid)); return r?JSON.parse(r):[]; } catch(e){ return []; } };
const saveBadgesStore = (uid, badges) => { try { localStorage.setItem(badgeKey(uid), JSON.stringify(badges)); } catch(e){} };
const joinKey = (uid) => `stfy_join_${uid}`;
const getJoinDate = (uid) => { 
  try { 
    let d = localStorage.getItem(joinKey(uid)); 
    if(!d){ d=new Date().toISOString(); localStorage.setItem(joinKey(uid),d); }
    return d;
  } catch(e){ return new Date().toISOString(); } 
};

// Draw a badge PNG as a data URL using canvas
function drawBadgePNG(def, toothImg, size=300) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  const cx = size/2, cy = size/2, r = size*0.47;

  // Background circle
  const grad = ctx.createRadialGradient(cx, cy-size*0.05, 0, cx, cy, r);
  grad.addColorStop(0, '#004D72');
  grad.addColorStop(1, '#001830');
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fillStyle=grad; ctx.fill();

  // Outer ring
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2);
  ctx.strokeStyle='#00AECC'; ctx.lineWidth=size*0.022; ctx.stroke();

  // Inner ring
  ctx.beginPath(); ctx.arc(cx, cy, r*0.88, 0, Math.PI*2);
  ctx.strokeStyle='rgba(0,174,204,0.35)'; ctx.lineWidth=size*0.008; ctx.stroke();

  // Type color stripe based on badge type
  const typeColors = {milestone:'#C8922A', identified:'#1A8F62', yearly:'#8B47D6', species:'#00AECC', manual:'#D62828'};
  const stripe = typeColors[def.type]||'#00AECC';

  // Decorative tick marks around ring
  for(let i=0;i<36;i++){
    const angle = (i/36)*Math.PI*2 - Math.PI/2;
    const len = i%3===0 ? size*0.045 : size*0.022;
    const x1=cx+Math.cos(angle)*(r-size*0.03), y1=cy+Math.sin(angle)*(r-size*0.03);
    const x2=cx+Math.cos(angle)*(r-size*0.03-len), y2=cy+Math.sin(angle)*(r-size*0.03-len);
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2);
    ctx.strokeStyle=i%3===0?stripe:'rgba(0,174,204,0.4)';
    ctx.lineWidth=i%3===0?size*0.012:size*0.005; ctx.stroke();
  }

  // SharkToothify wordmark at top
  ctx.fillStyle='rgba(0,174,204,0.7)';
  ctx.font=`bold ${size*0.055}px "DM Mono", monospace`;
  ctx.textAlign='center'; ctx.letterSpacing='2px';
  // App logo in center (replaces tooth emoji for ALL badges)
  const logoSize = toothImg ? size*0.28 : size*0.38;
  if(toothImg){
    // Species badges: logo at top center, tooth below
    // Logo centered at top
    ctx.save();
    ctx.shadowColor='rgba(0,200,240,0.5)'; ctx.shadowBlur=size*0.06;
    drawLogoOnCanvas(ctx, cx - size*0.14, cy - r*0.78, size*0.28);
    ctx.restore();
    // Tooth photo below logo
    const imgSize = size*0.30;
    ctx.save();
    ctx.shadowColor='rgba(0,200,240,0.5)'; ctx.shadowBlur=size*0.07;
    ctx.drawImage(toothImg, cx-imgSize/2, cy-r*0.35, imgSize, imgSize*1.1);
    ctx.restore();
  } else {
    // All other badges: large centered app logo
    ctx.save();
    ctx.shadowColor='rgba(0,200,240,0.7)'; ctx.shadowBlur=size*0.12;
    drawLogoOnCanvas(ctx, cx - logoSize*0.5, cy - r*0.55, logoSize);
    ctx.restore();
  }

  // Badge title
  ctx.fillStyle='#ffffff';
  ctx.shadowColor='rgba(0,0,0,0.9)'; ctx.shadowBlur=8; ctx.shadowOffsetX=0; ctx.shadowOffsetY=1;
  ctx.font=`bold ${size*0.075}px "DM Serif Display", serif`;
  ctx.textAlign='center';
  const title = def.title.toUpperCase();
  const words = title.split(' ');
  if(words.length<=2){
    ctx.fillText(title, cx, cy+r*0.22);
  } else {
    ctx.fillText(words.slice(0, Math.ceil(words.length/2)).join(' '), cx, cy+r*0.15);
    ctx.fillText(words.slice(Math.ceil(words.length/2)).join(' '), cx, cy+r*0.28);
  }

  // Type label
  ctx.fillStyle=stripe;
  ctx.font=`${size*0.052}px "DM Mono", monospace`;
  ctx.textAlign='center';
  const typeLabel = def.type==='milestone'?'MILESTONE BADGE':def.type==='identified'?'IDENTIFICATION BADGE':def.type==='yearly'?'YEARLY BADGE':def.type==='manual'?'MANUAL ID BADGE':'SPECIES BADGE';
  ctx.fillText(typeLabel, cx, cy+r*0.48);

  // Gold separator line
  ctx.beginPath();
  ctx.moveTo(cx-r*0.45, cy+r*0.56); ctx.lineTo(cx+r*0.45, cy+r*0.56);
  ctx.strokeStyle=stripe; ctx.lineWidth=size*0.007; ctx.stroke();

  // SHARKTOOTHIFY text — small, below the gold line
  ctx.fillStyle='rgba(0,174,204,0.65)';
  ctx.font=`${size*0.042}px "DM Mono", monospace`;
  ctx.textAlign='center';
  ctx.fillText('SHARKTOOTHIFY', cx, cy+r*0.70);

  return canvas.toDataURL('image/png');
}

function matchSpeciesKey(name) {
  if (!name) return null;
  const s = name.toLowerCase();
  if (s.includes('megalodon') || (s.includes('otodus') && !s.includes('chub') && !s.includes('angust') && !s.includes('auriculat'))) return 'megalodon';
  if (s.includes('chubutensis') || s.includes('chub')) return 'chubutensis';
  if (s.includes('auriculatus') || s.includes('auriculat')) return 'auriculatus';
  if (s.includes('carcharodon') || s.includes('great white') || s.includes('great-white')) return 'great_white';
  if ((s.includes('isurus') || s.includes('mako')) && !s.includes('parotodus')) return 'mako';
  if (s.includes('hexanchus') || s.includes('notorynchus') || s.includes('cow') || s.includes('sixgill') || s.includes('sevengill')) return 'cow';
  if (s.includes('sand tiger') || s.includes('carcharias taurus') || s.includes('odontaspis') || s.includes('eugomphodus')) return 'sand_tiger';
  if (s.includes('bull') || s.includes('leucas')) return 'bull';
  if (s.includes('hemipristis') || s.includes('snaggle') || s.includes('hemi')) return 'hemipristis';
  if ((s.includes('tiger') || s.includes('galeocerdo')) && !s.includes('sand') && !s.includes('thresher')) return 'tiger';
  if (s.includes('lemon') || s.includes('negaprion')) return 'lemon';
  if (s.includes('pygmy') || s.includes('squaliolus') || s.includes('dwarf')) return 'pygmy';
  // Extended species matching
  if (s.includes('thresher') || s.includes('alopias')) return 'thresher_shark';
  if (s.includes('shortfin mako') || (s.includes('mako') && s.includes('shortfin'))) return 'shortfin_mako';
  if (s.includes('longfin mako') || (s.includes('mako') && s.includes('longfin'))) return 'longfin_mako_ext_1';
  if (s.includes('isurus hastalis') || (s.includes('mako') && s.includes('extinct'))) return 'mako_ext_1';
  if (s.includes('mako') || s.includes('isurus')) return 'shortfin_mako';
  if (s.includes('cookiecutter') || s.includes('isistius')) return 'cookiecutter_shark';
  if (s.includes('whale shark') || s.includes('rhincodon')) return 'whale_shark';
  if (s.includes('prickly') || s.includes('echinorhinus')) return 'prickly_shark';
  if (s.includes('smalltooth') || s.includes('odontaspis ferox')) return 'smalltooth_sand_tiger';
  if (s.includes('silky') || s.includes('falciformis')) return 'silky_shark_1';
  if (s.includes('dusky') || s.includes('obscurus')) return 'dusky_shark_1';
  if (s.includes('copper') || s.includes('brachyurus')) return 'copper_shark_1';
  if (s.includes('physogaleus') || (s.includes('tiger') && s.includes('extinct'))) return 'tiger_like_ext_1';
  if (s.includes('parotodus') || s.includes('benedeni') || s.includes('lamnoid')) return 'extinct_lamnoid';
  if (s.includes('serrated')) return 'serrated_shark_1';
  if (s.includes('sphyrna') || s.includes('hammerhead')) return 'bull';
  if (s.includes('carcharh') || s.includes('reef') || s.includes('requiem')) return 'requiem_unid';
  return null;
}

